l('decay','Phân rã phóng xạ',12,'Hạt nhân','Theo dõi số hạt còn lại qua các chu kì bán rã.',[p('n0','Số hạt ban đầu',100,2000,100,1000,'',0),p('half','Chu kì bán rã',1,10,.5,4,'s'),time(50,.1)],['t (s)','N kỳ vọng','N đã phân rã','H (Bq)','T½ (s)'],'N = N₀ 2⁻ᵗ/ᵀ; H = λN','Số đọc là giá trị kỳ vọng của mẫu. Các điểm 3D minh họa tính ngẫu nhiên; mỗi điểm đại diện một phần của mẫu.',['Ghi số hạt tại t = 0, T½ và 2T½.','Đổi số hạt ban đầu.','Kiểm tra sau mỗi chu kì bán rã số hạt kỳ vọng giảm một nửa.'])
